<?php
declare(strict_types=1);require __DIR__.'/config.php';require __DIR__.'/functions.php';require_admin();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='save'){$name=trim($_POST['name']??'');$icon=trim($_POST['icon']??'✦');$slug=slugify($name);if($name){if($id)$pdo->prepare('UPDATE categories SET name=?,slug=?,icon=? WHERE id=?')->execute([$name,$slug,$icon,$id]);else $pdo->prepare('INSERT INTO categories(name,slug,icon) VALUES(?,?,?)')->execute([$name,$slug,$icon]);set_flash('success','Kategori berhasil disimpan.');}}elseif($action==='delete'){$pdo->prepare('UPDATE twibbons SET category_id=NULL WHERE category_id=?')->execute([$id]);$pdo->prepare('DELETE FROM categories WHERE id=?')->execute([$id]);set_flash('success','Kategori dihapus.');}redirect('categories');}
$items=$pdo->query('SELECT c.*,COUNT(t.id) total FROM categories c LEFT JOIN twibbons t ON t.category_id=c.id GROUP BY c.id ORDER BY c.name')->fetchAll();$flash=get_flash();
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kategori — Semarakin</title><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="teal.css"><link rel="stylesheet" href="auth.css"></head><body><header class="site-header"><div class="container nav"><a class="brand" href="./"><span class="brand-mark">S</span>Semarakin</a></div></header><main class="container"><div class="page-head"><span class="eyebrow">Administrator</span><h1 class="page-title">Kategori karya</h1><p class="subtitle">Bantu audiens menemukan kampanye yang relevan.</p></div><?php if($flash):?><div class="alert alert-<?=e($flash['type'])?>"><?=e($flash['message'])?></div><?php endif?><div class="creator-studio"><section class="panel"><h2>Kategori baru</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><div class="field"><label>Nama</label><input name="name" required maxlength="80"></div><div class="field"><label>Ikon singkat</label><input name="icon" value="✦" maxlength="20"></div><button class="btn btn-primary">Tambahkan</button></form></section><section class="studio-list"><?php foreach($items as $item):?><article class="studio-item"><div class="category-icon"><?=e($item['icon'])?></div><div><h3><?=e($item['name'])?></h3><p><?=(int)$item['total']?> karya · /<?=e($item['slug'])?></p></div><form method="post" data-confirm="Hapus kategori ini?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="btn btn-danger btn-sm">Hapus</button></form></article><?php endforeach?></section></div></main><footer class="footer">Semarakin · Apins Digital</footer></body></html>
